(* [comment removed for export] *)
Lemma hd_app_if : forall (lg lt : list qbatch),
  hd 0 (map qb_addr (lg ++ lt)) = (if zlen lg =? 0 then hd 0 (map qb_addr lt) else hd 0 (map qb_addr lg)).
Proof.
  intros [|b r] lt; [rewrite zlen_nil', Z.eqb_refl; reflexivity|].
  rewrite zlen_cons'. replace (1 + zlen r =? 0) with false by (symmetry; apply Z.eqb_neq; pose proof (zlen_nonneg r); unfold zlen in *; olia). reflexivity.
Qed.
Lemma last_app_ne : forall (lg lt : list qbatch), lt <> [] -> last (map qb_addr (lg ++ lt)) 0 = last (map qb_addr lt) 0.
Proof. intros lg lt NE. rewrite map_app. apply last_app_nonnil. destruct lt; [exact (fun _ => NE eq_refl)| discriminate]. Qed.

(* [comment removed for export] *)
Lemma sbs_set_gq_transfer : forall a b q, same_but_shadow a b -> same_but_shadow (set_gq (transfer_m a) q) (set_gq (transfer_m b) q).
Proof.
  intros a b q H. destruct H as (H1 & H2 & H3 & H4 & H5 & H6 & H7 & H8 & H9 & H10 & H11 & H12 & H13 & H14 & H15 & H16).
  unfold same_but_shadow, set_gq, transfer_m, set_tq. cbn. rewrite H1, H2, H3, H4, H5, H6, H7, H8, H11, H12, H13, H14, H15, H16. repeat split; reflexivity.
Qed.

