  Theorem free_tail2_raw : forall (sm : ast) (msF2 : machine_state) (mo2 : Model)
      (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (jk : list byte) (rest : list word) (m2 : mem),
    a_thr sm = a_thr s -> a_top sm = a_top s -> a_bot sm = a_bot s ->
    qc_list (as_tq (a_st sm)) <> [] -> 0 <= qc_bytes (as_tq (a_st sm)) <= kMaxCacheSize + kQuarantineMaxSize + kBatchSize ->
    0 <= qc_bytes (as_gq (a_st sm)) <= kQuarantineMaxSize ->
    lzok asegs (a_L sm) (a_S sm) (a_Zr sm) (mkCfg msF2 mo2) ->
    restrict (a_L sm) (a_S sm) msF2
       = MS (enq_regs sp gp tp s7 s8 s9 s10 s11 U size TH kMaxCacheSize t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6') F (Z_to_bv 64 0x53358) fc None m2 (seg_rom asegs) ->
    ARHEAPQ sm [] [] LB' m2 -> awin_vis sm m2 -> flagsx_rep m2 -> AMODELX sm mo2 ->
    DEPOT asegs d' m2 -> depot_placed sm d' -> depot_cov d' mo2 ->
    mem_inv asegs m2 -> stk asegs m2 lo (bv_unsigned sp + -2208) ->
    rw_cells asegs m2 (bv_unsigned sp + -2208) (put_frame sp s6 U TH) ->
    rw_cells asegs m2 (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))] ->
    u64arr asegs m2 (bv_unsigned sp + -2128 + 16) (map wz T ++ rest) -> length rest = (255 - length T)%nat -> (1 <= length T <= 30)%nat ->
    rw_cells asegs m2 (bv_unsigned sp + -72) [C8 sp] ->
    rw_cells asegs m2 (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    (* [comment removed for export] *)
    kMaxCacheSize < qc_bytes (as_tq (a_st sm)) -> kQuarantineMaxSize < qc_bytes (as_gq (a_st sm)) + qc_bytes (as_tq (a_st sm)) ->
    as_cache_inited (a_st sm) = true -> NUM (a_st sm) ->
    (forall msF' mo', rstep_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc sm d' lo m2 mo2 [] [] [] (MREC sm) msF' mo' ->
                      sreach asegs Q (mkCfg msF' mo')) ->
    sreach asegs Q (mkCfg msF2 mo2).
  Proof.
